-- ----------------------------------------------------------------- claiming
-- Claim work for a worker. Expired leases of running executions are reclaimed
-- first (crash recovery); otherwise the oldest pending event starts a new
-- execution. SKIP LOCKED lets several workers claim concurrently without
-- handing the same work to two of them. Every claim bumps `attempt`, which
-- is the fencing token all later writes must present.
create or replace function cornucopia.claim_next_execution(
  p_organization_id uuid, p_worker text, p_lease_seconds int
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_exec cornucopia.agent_executions;
  v_event cornucopia.operational_events;
begin
  if p_lease_seconds not between 5 and 3600 then
    raise exception 'lease must be 5..3600 seconds' using errcode = 'P0422';
  end if;

  select * into v_exec from cornucopia.agent_executions
   where organization_id = p_organization_id and status = 'running' and lease_expires_at < now()
   order by created_at
   for update skip locked
   limit 1;
  if found then
    update cornucopia.agent_executions
       set lease_owner = p_worker, attempt = attempt + 1,
           lease_expires_at = now() + make_interval(secs => p_lease_seconds), heartbeat_at = now()
     where id = v_exec.id
     returning * into v_exec;
    insert into cornucopia.agent_execution_steps (execution_id, attempt, node, status, detail)
    values (v_exec.id, v_exec.attempt, coalesce(v_exec.current_node, 'supervisor'), 'resumed',
            jsonb_build_object('worker', p_worker, 'previous_owner_lease_expired', true));
    select * into v_event from cornucopia.operational_events where id = v_exec.event_id;
    return jsonb_build_object('resumed', true, 'execution', to_jsonb(v_exec), 'event', to_jsonb(v_event));
  end if;

  select * into v_event from cornucopia.operational_events
   where organization_id = p_organization_id and processing_status = 'pending'
   order by created_at, id
   for update skip locked
   limit 1;
  if not found then
    return null;
  end if;
  insert into cornucopia.agent_executions (organization_id, event_id, thread_id, correlation_id, status,
                                           attempt, lease_owner, lease_expires_at, heartbeat_at)
  values (p_organization_id, v_event.id, 'event:' || v_event.id, v_event.correlation_id, 'running',
          1, p_worker, now() + make_interval(secs => p_lease_seconds), now())
  on conflict (event_id) do nothing
  returning * into v_exec;
  if v_exec.id is null then
    -- an execution already exists for this event (e.g. finished earlier): never run twice
    update cornucopia.operational_events set processing_status = 'processed',
           processing_note = 'execution already exists' where id = v_event.id;
    return null;
  end if;
  update cornucopia.operational_events set processing_status = 'processing' where id = v_event.id;
  insert into cornucopia.agent_execution_steps (execution_id, attempt, node, status, detail)
  values (v_exec.id, 1, 'supervisor', 'claimed', jsonb_build_object('worker', p_worker));
  return jsonb_build_object('resumed', false, 'execution', to_jsonb(v_exec), 'event', to_jsonb(v_event));
end $$;

create or replace function cornucopia._holds_lease(p_exec uuid, p_worker text, p_attempt int)
returns boolean language sql stable set search_path = '' as $$
  select exists (select 1 from cornucopia.agent_executions
                  where id = p_exec and lease_owner = p_worker and attempt = p_attempt
                    and status = 'running' and lease_expires_at >= now());
$$;

create or replace function cornucopia.heartbeat_execution(
  p_execution_id uuid, p_worker text, p_attempt int, p_lease_seconds int
) returns boolean language plpgsql security definer set search_path = '' as $$
begin
  update cornucopia.agent_executions
     set lease_expires_at = now() + make_interval(secs => p_lease_seconds), heartbeat_at = now()
   where id = p_execution_id and lease_owner = p_worker and attempt = p_attempt and status = 'running';
  return found;
end $$;

create or replace function cornucopia.record_execution_step(
  p_execution_id uuid, p_worker text, p_attempt int, p_node text, p_status text, p_detail jsonb
) returns boolean language plpgsql security definer set search_path = '' as $$
begin
  if not cornucopia._holds_lease(p_execution_id, p_worker, p_attempt) then
    return false;  -- fenced: a newer attempt owns this execution
  end if;
  insert into cornucopia.agent_execution_steps (execution_id, attempt, node, status, detail)
  values (p_execution_id, p_attempt, p_node, p_status, coalesce(p_detail, '{}'::jsonb));
  update cornucopia.agent_executions
     set current_node = p_node,
         last_completed_node = case when p_status = 'completed' then p_node else last_completed_node end,
         retry_count = retry_count + case when p_status = 'retry' then 1 else 0 end
   where id = p_execution_id;
  return true;
end $$;

create or replace function cornucopia.finish_execution(
  p_execution_id uuid, p_worker text, p_attempt int, p_status text, p_result jsonb, p_error text
) returns boolean language plpgsql security definer set search_path = '' as $$
declare
  v_event uuid;
begin
  if p_status not in ('awaiting_approval','completed','escalated','failed') then
    raise exception 'invalid final status %', p_status using errcode = 'P0422';
  end if;
  if not cornucopia._holds_lease(p_execution_id, p_worker, p_attempt) then
    return false;
  end if;
  update cornucopia.agent_executions
     set status = p_status, result = p_result, error = p_error, finished_at = now(),
         lease_owner = null, lease_expires_at = null
   where id = p_execution_id
   returning event_id into v_event;
  update cornucopia.operational_events
     set processing_status = case p_status when 'escalated' then 'escalated'
                                           when 'failed' then 'failed' else 'processed' end,
         processing_note = case p_status when 'awaiting_approval' then 'recovery proposal awaiting approval'
                                         when 'completed' then 'no recovery needed'
                                         else left(coalesce(p_error, p_status), 500) end,
         processed_at = now()
   where id = v_event;
  return true;
end $$;

-- -------------------------------------------------------------- checkpoints
create or replace function cornucopia.put_checkpoint(p_row jsonb)
returns boolean language plpgsql security definer set search_path = '' as $$
begin
  insert into cornucopia.agent_checkpoints (thread_id, checkpoint_ns, checkpoint_id, organization_id,
    parent_checkpoint_id, checkpoint_type, checkpoint, metadata_type, metadata, summary)
  values (p_row ->> 'thread_id', p_row ->> 'checkpoint_ns', p_row ->> 'checkpoint_id',
    (p_row ->> 'organization_id')::uuid, p_row ->> 'parent_checkpoint_id', p_row ->> 'checkpoint_type',
    p_row ->> 'checkpoint', p_row ->> 'metadata_type', p_row ->> 'metadata', p_row -> 'summary')
  on conflict do nothing;  -- checkpoints are immutable; a replayed put is a no-op
  return true;
end $$;

create or replace function cornucopia.put_checkpoint_writes(p_rows jsonb)
returns int language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  insert into cornucopia.agent_checkpoint_writes as w (thread_id, checkpoint_ns, checkpoint_id, task_id, idx,
    organization_id, channel, value_type, value, task_path)
  select r ->> 'thread_id', r ->> 'checkpoint_ns', r ->> 'checkpoint_id', r ->> 'task_id', (r ->> 'idx')::int,
         (r ->> 'organization_id')::uuid, r ->> 'channel', r ->> 'value_type', r ->> 'value',
         coalesce(r ->> 'task_path', '')
    from jsonb_array_elements(p_rows) r
  on conflict (thread_id, checkpoint_ns, checkpoint_id, task_id, idx) do update
     set channel = excluded.channel, value_type = excluded.value_type, value = excluded.value
   where w.idx < 0;  -- special writes (errors, interrupts) may be replaced; regular ones never
  get diagnostics n = row_count;
  return n;
end $$;

-- -------------------------------------------- idempotent optimization runs
create or replace function cornucopia.record_optimization_run(
  p_organization_id uuid, p_actor text, p_run jsonb, p_results jsonb
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid;
  v_key text := p_run ->> 'idempotency_key';
begin
  if v_key is not null then
    perform pg_advisory_xact_lock(hashtextextended('optrun/' || v_key, 0));
    select id into v_id from cornucopia.optimization_runs where idempotency_key = v_key;
    if found then
      return jsonb_build_object('run_id', v_id, 'duplicate', true);
    end if;
  end if;
  if jsonb_typeof(p_results) <> 'array' or jsonb_array_length(p_results) = 0 then
    raise exception 'an optimization run needs at least one result' using errcode = 'P0422';
  end if;
  if (select count(*) from jsonb_array_elements(p_results) r where (r ->> 'recommended')::boolean) <> 1 then
    raise exception 'exactly one result must be recommended' using errcode = 'P0422';
  end if;
  v_id := gen_random_uuid();
  insert into cornucopia.optimization_runs (id, organization_id, state_version, requested_by, correlation_id,
    config, solver_status, verdict, objectives, stages, model_stats, diagnosis, wall_ms, idempotency_key)
  values (v_id, p_organization_id, (p_run ->> 'state_version')::bigint, p_actor,
    (p_run ->> 'correlation_id')::uuid, p_run -> 'config', p_run ->> 'solver_status', p_run ->> 'verdict',
    p_run -> 'objectives', p_run -> 'stages', p_run -> 'model_stats', p_run -> 'diagnosis',
    (p_run ->> 'wall_ms')::numeric, v_key);
  insert into cornucopia.optimization_results (run_id, candidate, recommended, verdict, fingerprint,
    meals_planned, plan, summary)
  select v_id, r ->> 'candidate', (r ->> 'recommended')::boolean, r ->> 'verdict', r ->> 'fingerprint',
         (r ->> 'meals_planned')::int, r -> 'plan', r -> 'summary'
    from jsonb_array_elements(p_results) r;
  return jsonb_build_object('run_id', v_id, 'duplicate', false);
end $$;

